mapper.select:
SELECT 
  FROM public.agent_runtime_executions
 WHERE tenant_id = #{tenantId} AND execution_id = #{executionId}

SELECT 
  FROM public.agent_runtime_executions
 WHERE tenant_id = #{tenantId}
   AND state IN ('QUEUED', 'RUNNING', 'WAITING_HITL', 'WAITING_EXTERNAL', 'RESUMING')

   AND execution_id > #{afterExecutionId}

 ORDER BY execution_id
 LIMIT #{limit}

SELECT 
  FROM public.agent_runtime_execution_mutations
 WHERE tenant_id = #{tenantId} AND execution_id = #{executionId}
   AND mutation_key = #{mutationKey}

SELECT 
  FROM public.agent_runtime_execution_publication_mutations
 WHERE tenant_id = #{tenantId} AND source_id = #{sourceId}
   AND event_id = #{eventId} AND mutation_key = #{mutationKey}
